159			"ACCESSIBLE=1",
160	
161			// See https://code.claude.com/docs/en/settings - without this setting Claude was going off and
162			// trying to Git-clone its plugin marketplace, which meant calling git commands that could fail
163			// due to a user's exotic config (e.g. in paul's case, needing SSH-keychain access granted every
164			// time).  That's no good, so for the E2E tests, we tell Claude not to make calls to auto-update
165			// itself, clone its plugins, etc.
166			"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1",
167			"CLAUDE_CONFIG_DIR=" + configDir,
168		}
169	
170		args := append([]string{"env"}, envArgs...)
171		args = append(args, c.Binary(), "--dangerously-skip-permissions")
172		s, err := NewTmuxSession(name, dir, []string{"CLAUDECODE", "ENTIRE_TEST_TTY"}, args[0], args[1:]...)
173		if err != nil {
174			_ = os.RemoveAll(configDir)
175			return nil, err
176		}
177		s.OnClose(func() { _ = os.RemoveAll(configDir) })
178	
179		// Dismiss startup dialogs until we reach the input prompt.
180		for range 5 {
181			content, err := s.WaitFor(`❯`, 15*time.Second)
182			if err != nil {
183				_ = s.Close()
184				return nil, fmt.Errorf("waiting for startup prompt: %w", err)
185			}
186			if !strings.Contains(content, "Enter to confirm") {
187				break
188			}
189			// Permission and workspace-trust dialogs both default to a negative
190			// option, so walk down to the affirmative one before confirming. Only
191			// dialogs that offer such a choice get the walk — first-run dialogs
192			// like theme selection also say "Enter to confirm" and are answered by
193			// their default. Once committed to the walk, bail rather than confirm
194			// blind: Enter on the wrong option quits Claude, and that surfaces as
195			// the next iteration's "waiting for startup prompt" timeout, which
196			// hides the cause.
197			if claudeStartupOffersYes(content) {
198				for range 3 {
199					if claudeStartupSelectionIsYes(content) {
200						break
201					}
202					_ = s.SendKeys("Down")
203					time.Sleep(200 * time.Millisecond)
204					content = s.Capture()
205				}
206				if !claudeStartupSelectionIsYes(content) {
207					_ = s.Close()
208					return nil, fmt.Errorf("startup dialog: affirmative option not reachable, wording may have changed\n%s", content)
209				}
210			}
211			_ = s.SendKeys("Enter")
212			time.Sleep(500 * time.Millisecond)
213		}
214		s.stableAtSend = ""
215	
216		return s, nil
217	}
