219	// claudeStartupOffersYes reports whether the dialog presents an affirmative
220	// option at all, distinguishing a trust/permission choice from a first-run
221	// dialog whose default answer is the right one.
222	func claudeStartupOffersYes(content string) bool {
223		return strings.Contains(strings.ToLower(content), "yes")
224	}
225	
226	// claudeStartupSelectionIsYes reports whether the highlighted option in a
227	// startup dialog is the affirmative one. It keys on the affirmative wording
228	// rather than the negative because both are release-dependent, and only one of
229	// them is safe to press Enter on: a reworded negative ("No, cancel") read as
230	// affirmative quits Claude, while a reworded affirmative merely costs another
231	// Down keypress.
232	// The dialog renders below whatever it was drawn over, so the last cursor line
233	// in the pane is its selection; an earlier "❯" belongs to prior content.
234	func claudeStartupSelectionIsYes(content string) bool {
235		selected := ""
236		for line := range strings.SplitSeq(content, "\n") {
237			if strings.Contains(line, "❯") {
238				selected = line
239			}
240		}
241		return strings.Contains(strings.ToLower(selected), "yes")
242	}
